import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useMatchStore } from '../../store/matchStore';
import { useAppStore } from '../../store/appStore';
import { useOnlineStore } from '../../store/onlineStore';
import { startOnlineSync } from '../../services/onlineGame';
import { Board } from '../../components/board';
import type { BoardLabels, BoardSpot } from '../../components/board';
import { Dice } from '../../components/dice';
import {
  fromToSpot,
  spotToNumber,
  toDiceItems,
  toPointViews,
  toToSpot,
} from './boardAdapter';

import eagleImg from '../../assets/images/eagle.jpg';
import motherImg from '../../assets/images/mother.jpg';
import mountainsImg from '../../assets/images/mountains.jpg';

const BACKGROUND_IMAGES = [eagleImg, motherImg, mountainsImg];

interface GameBoardScreenProps {
  onExit?: () => void;
}

export function GameBoardScreen({ onExit }: GameBoardScreenProps) {
  const { t } = useTranslation();

  const [randomBackground, setRandomBackground] = useState<string | null>(null);

  const mode = useMatchStore((s) => s.mode);
  const playerColor = useMatchStore((s) => s.playerColor);
  const gameState = useMatchStore((s) => s.gameState);
  const selectedPoint = useMatchStore((s) => s.selectedPoint);
  const targetMoves = useMatchStore((s) => s.targetMoves);
  const aiThinking = useMatchStore((s) => s.aiThinking);
  const turnTimeLeft = useMatchStore((s) => s.turnTimeLeft);
  const warnings = useMatchStore((s) => s.warnings);
  const timeoutMessage = useMatchStore((s) => s.timeoutMessage);
  const tickTimer = useMatchStore((s) => s.tickTimer);

  const onlineRoomId = useOnlineStore((s) => s.match?.roomId);

  const reducedMotion = useAppStore((s) => s.reducedMotion);

  const startMatch = useMatchStore((s) => s.startMatch);
  const rollDice = useMatchStore((s) => s.rollDice);
  const selectPoint = useMatchStore((s) => s.selectPoint);
  const aiTurn = useMatchStore((s) => s.aiTurn);
  const resetMatch = useMatchStore((s) => s.resetMatch);

  // تایمر ۴۵ ثانیه و سه اخطار فقط در بازی‌های غیر ربات (آنلاین) فعال است
  const hasTimer = mode !== 'ai';

  useEffect(() => {
    if (!randomBackground) {
      const randomIndex = Math.floor(Math.random() * BACKGROUND_IMAGES.length);
      setRandomBackground(BACKGROUND_IMAGES[randomIndex]);
    }
  }, [randomBackground]);

  useEffect(() => {
    if (!gameState) startMatch();
  }, [gameState, startMatch]);

  // همگام‌سازی بازی آنلاین با حریف
  useEffect(() => {
    if (mode !== 'online' || !onlineRoomId) return;
    return startOnlineSync(onlineRoomId);
  }, [mode, onlineRoomId]);

  useEffect(() => {
    if (!hasTimer) return;
    if (!gameState || gameState.phase === 'ended') return;

    const interval = setInterval(() => {
      tickTimer();
    }, 1000);
    return () => clearInterval(interval);
  }, [hasTimer, gameState, tickTimer]);

  useEffect(() => {
    if (!gameState || mode !== 'ai') return;
    if (gameState.phase === 'ended') return;
    if (gameState.turn === playerColor) return;
    if (aiThinking) return;
    aiTurn();
  }, [gameState, mode, playerColor, aiThinking, aiTurn]);

  const labels: BoardLabels = useMemo(
    () => ({
      point: (n: number) => t('game.point', { n }),
      bar: t('game.bar'),
      home: t('game.home'),
    }),
    [t],
  );

  if (!gameState) return null;

  const { turn, phase, winner, board } = gameState;
  const isHumanTurn = mode === 'local' || turn === playerColor;
  const canRoll = isHumanTurn && phase === 'rolling' && !aiThinking;
  const canTap = isHumanTurn && phase === 'moving' && !aiThinking;

  const selected: BoardSpot | null =
    selectedPoint !== null ? fromToSpot(selectedPoint, turn) : null;

  const targets: BoardSpot[] = reducedMotion
    ? []
    : targetMoves.map((m) => toToSpot(m.to, turn));

  const handleSpotClick = (spot: BoardSpot) => {
    if (!canTap) return;
    selectPoint(spotToNumber(spot, turn));
  };

  const vsOpponent = mode === 'ai' || mode === 'online';

  let status: string;
  if (aiThinking) status = t('game.aiThinking');
  else if (vsOpponent) status = isHumanTurn ? t('game.yourTurn') : t('game.opponentTurn');
  else status = turn === 'white' ? t('game.whiteTurn') : t('game.blackTurn');

  let winText = '';
  if (phase === 'ended' && winner) {
    winText = vsOpponent
      ? winner === playerColor
        ? t('game.youWin')
        : t('game.youLose')
      : winner === 'white'
        ? t('game.whiteWins')
        : t('game.blackWins');
  }

  const handleExit = () => {
    resetMatch();
    onExit?.();
  };

  const currentWarnings = warnings[turn] || 0;

  return (
    <div
      className="relative flex h-full w-full flex-row gap-2 overflow-hidden bg-black bg-cover bg-center p-2 text-amber-50 select-none"
      style={{
        backgroundImage: randomBackground ? `url(${randomBackground})` : 'none',
      }}
    >
      <div className="absolute inset-0 z-0 bg-black/70" />

      {/* تخته: تمام فضای باقی‌مانده */}
      <div className="relative z-10 h-full min-w-0 flex-1">
        <Board
          points={toPointViews(board.points)}
          bar={board.bar}
          off={board.off}
          selected={selected}
          targets={targets}
          labels={labels}
          onSpotClick={handleSpotClick}
        />
      </div>

      {/* ستون کناری: منو، وضعیت، تاس */}
      <div className="relative z-10 flex h-full w-28 shrink-0 flex-col items-center justify-between py-1">
        <div className="flex w-full flex-col items-center gap-2">
          <button
            type="button"
            onClick={handleExit}
            className="w-full rounded-full bg-stone-700/80 px-3 py-1.5 text-xs font-semibold text-amber-100 active:scale-95"
          >
            {t('game.menu')}
          </button>
          <span className="text-center text-xs font-semibold leading-tight text-amber-200">
            {status}
          </span>
          {hasTimer && phase !== 'ended' && (
            <div className="flex items-center gap-1 rounded-full border border-amber-500/30 bg-stone-800 px-2 py-1 text-xs font-bold text-amber-400">
              <span>⏳ {turnTimeLeft}s</span>
              <span className="text-[10px] text-red-400">({currentWarnings}/3)</span>
            </div>
          )}
        </div>

        <div className="flex min-h-[60px] w-full items-center justify-center">
          <Dice
            dice={toDiceItems(gameState)}
            canRoll={canRoll}
            onRoll={rollDice}
            rollLabel={t('game.roll')}
          />
        </div>

        <div className="h-1" />
      </div>

      {hasTimer && timeoutMessage && (
        <div className="absolute left-1/2 top-2 z-40 -translate-x-1/2 animate-bounce rounded-xl bg-red-600/90 px-3 py-1 text-xs font-bold text-white shadow-lg">
          {timeoutMessage}
        </div>
      )}

      {/* پایان بازی */}
      {phase === 'ended' && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 p-6 backdrop-blur-sm">
          <div className="flex w-full max-w-xs flex-col items-center gap-3 rounded-2xl border border-amber-500/30 bg-stone-800 p-5 text-center shadow-2xl">
            <h2 className="text-xl font-bold text-amber-300">{winText}</h2>
            {mode !== 'online' && (
              <button
                type="button"
                onClick={startMatch}
                className="w-full rounded-full bg-amber-500 px-6 py-2.5 text-sm font-bold text-stone-900 shadow-md active:scale-95"
              >
                {t('game.newGame')}
              </button>
            )}
            <button
              type="button"
              onClick={handleExit}
              className="w-full rounded-full bg-stone-700 px-6 py-2.5 text-sm font-semibold text-gray-200 active:scale-95"
            >
              {t('game.menu')}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default GameBoardScreen;
