import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useHaptic } from '@/hooks/useHaptic';
import { useTelegram } from '@/hooks/useTelegram';
import { useAppStore } from '@/store/appStore';
import { useMatchStore } from '@/store/matchStore';
import { useOnlineStore } from '@/store/onlineStore';
import {
  createClientId,
  startMatchmaking,
  type MatchFound,
} from '@/services/matchmaking';
import { startOnlineMatch } from '@/services/onlineGame';

/** How long we search for an online opponent before suggesting the bot. */
const SEARCH_SECONDS = 10;

export function SearchOpponentScreen() {
  const { t } = useTranslation();
  const { impact } = useHaptic();
  const { displayName } = useTelegram();
  const goToMenu = useAppStore((s) => s.goToMenu);
  const setScreen = useAppStore((s) => s.setScreen);
  const resetDraft = useMatchStore((s) => s.resetDraft);
  const setMatch = useOnlineStore((s) => s.setMatch);

  const [secondsLeft, setSecondsLeft] = useState(SEARCH_SECONDS);
  const [found, setFound] = useState<MatchFound | null>(null);
  const stopRef = useRef<(() => void) | null>(null);

  // Join the lobby once when the screen opens
  useEffect(() => {
    setMatch(null);
    stopRef.current = startMatchmaking(
      { id: createClientId(), name: displayName },
      (match) => {
        setMatch(match);
        setFound(match);
      },
      () => setSecondsLeft(0), // no server / error -> "nobody online"
    );
    return () => stopRef.current?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // One tick per second; stop searching when the time is over
  useEffect(() => {
    if (found) return;
    if (secondsLeft <= 0) {
      stopRef.current?.();
      return;
    }
    const id = setTimeout(() => setSecondsLeft((s) => s - 1), 1000);
    return () => clearTimeout(id);
  }, [secondsLeft, found]);

  // Opponent found -> short pause, then both phones open the game
  useEffect(() => {
    if (!found) return;
    const id = setTimeout(() => {
      startOnlineMatch(found.myColor);
      setScreen('game');
    }, 1500);
    return () => clearTimeout(id);
  }, [found, setScreen]);

  const notFound = !found && secondsLeft <= 0;

  const onCancel = () => {
    impact('light');
    stopRef.current?.();
    goToMenu();
  };

  const onPlayBot = () => {
    impact('medium');
    resetDraft();
    setScreen('setup');
  };

  const progress = ((SEARCH_SECONDS - secondsLeft) / SEARCH_SECONDS) * 100;

  return (
    <div className="screen-shell items-center justify-center px-6 py-8">
      <div className="flex w-full max-w-sm flex-col items-center gap-6 text-center">
        {found ? (
          <>
            <div className="text-5xl">🎉</div>
            <h1 className="font-display text-2xl font-semibold text-gold">
              {t('search.found')}
            </h1>
            <p className="text-lg text-gold-soft">
              {t('search.opponentName', { name: found.opponentName })}
            </p>
            <p className="text-sm text-cream/70">
              {t('search.yourColor', {
                color:
                  found.myColor === 'white'
                    ? t('setup.colorWhite')
                    : t('setup.colorBlack'),
              })}
            </p>
            <p className="text-sm text-gold/80">{t('search.starting')}</p>
          </>
        ) : !notFound ? (
          <>
            <div className="h-16 w-16 animate-spin rounded-full border-4 border-gold/20 border-t-gold" />
            <h1 className="font-display text-2xl font-semibold text-gold">
              {t('search.searching')}
            </h1>
            <div className="rounded-full border border-gold/30 bg-wood-deep/70 px-5 py-2 text-base font-bold text-gold-soft">
              ⏳ {t('search.timeLeft', { s: secondsLeft })}
            </div>
            <div className="h-2 w-full overflow-hidden rounded-full bg-wood-deep/70">
              <div
                className="h-full rounded-full bg-gold transition-all duration-1000 ease-linear"
                style={{ width: `${progress}%` }}
              />
            </div>
            <button type="button" className="btn-ghost" onClick={onCancel}>
              {t('common.cancel')}
            </button>
          </>
        ) : (
          <>
            <div className="text-5xl">🤖</div>
            <h1 className="font-display text-2xl font-semibold text-gold">
              {t('search.notFound')}
            </h1>
            <p className="text-sm text-cream/70">{t('search.notFoundHint')}</p>
            <button type="button" className="btn-primary" onClick={onPlayBot}>
              {t('menu.playVsAi')}
            </button>
            <button type="button" className="btn-ghost" onClick={onCancel}>
              {t('game.backToMenu')}
            </button>
          </>
        )}
      </div>
    </div>
  );
}
