import { supabase } from './supabase';

export type MatchFound = {
  roomId: string;
  myColor: 'white' | 'black';
  opponentId: string;
  opponentName: string;
};

type Waiting = { id: string; name: string; joinedAt: number };

export function createClientId(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

/**
 * Join the lobby and wait for a partner.
 * Returns a function that stops searching.
 */
export function startMatchmaking(
  me: { id: string; name: string },
  onFound: (match: MatchFound) => void,
  onError: () => void,
): () => void {
  const client = supabase;
  if (!client) {
    onError();
    return () => {};
  }

  const joinedAt = Date.now();
  let done = false;

  const channel = client.channel('nard-lobby', {
    config: { presence: { key: me.id } },
  });

  const check = () => {
    if (done) return;

    const state = channel.presenceState<Waiting>();
    const byId = new Map<string, Waiting>();
    for (const entries of Object.values(state)) {
      for (const p of entries) {
        byId.set(p.id, { id: p.id, name: p.name, joinedAt: p.joinedAt });
      }
    }

    const list = [...byId.values()].sort(
      (a, b) => a.joinedAt - b.joinedAt || a.id.localeCompare(b.id),
    );

    const index = list.findIndex((p) => p.id === me.id);
    if (index === -1) return;

    // 0↔1, 2↔3, ...
    const partner = index % 2 === 0 ? list[index + 1] : list[index - 1];
    if (!partner) return;

    done = true;
    onFound({
      roomId: [me.id, partner.id].sort().join('_'),
      myColor: index % 2 === 0 ? 'white' : 'black',
      opponentId: partner.id,
      opponentName: partner.name,
    });

    // Stay a moment so the partner can also see us, then leave the lobby.
    setTimeout(() => {
      void client.removeChannel(channel);
    }, 2500);
  };

  channel
    .on('presence', { event: 'sync' }, check)
    .subscribe(async (status) => {
      if (status === 'SUBSCRIBED') {
        await channel.track({ id: me.id, name: me.name, joinedAt });
      } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
        if (!done) onError();
      }
    });

  return () => {
    if (!done) void client.removeChannel(channel);
  };
}
