import { create } from 'zustand';

export type OnlineMatch = {
  roomId: string;
  myColor: 'white' | 'black';
  opponentId: string;
  opponentName: string;
};

type OnlineState = {
  match: OnlineMatch | null;
  setMatch: (match: OnlineMatch | null) => void;
};

export const useOnlineStore = create<OnlineState>((set) => ({
  match: null,
  setMatch: (match) => set({ match }),
}));
