import type { CheckerColor } from './boardTypes';

interface CheckerProps {
  color: CheckerColor;
  selected?: boolean;
  badge?: number;
  size?: string; // e.g. "min(100cqw, 17cqh)"; if empty, fills the width
}

export function Checker({ color, selected = false, badge, size }: CheckerProps) {
  const look =
    color === 'white'
      ? 'bg-stone-100 border-stone-300 text-stone-900'
      : 'bg-stone-900 border-stone-600 text-stone-100';

  return (
    <div
      style={size ? { width: size, height: size } : undefined}
      className={`relative flex shrink-0 items-center justify-center rounded-full border-2 shadow-md ${
        size ? '' : 'aspect-square w-full'
      } ${look} ${selected ? 'ring-4 ring-amber-400' : ''}`}
    >
      <div className="absolute inset-[18%] rounded-full border border-current opacity-20" />
      {badge !== undefined && (
        <span className="relative text-[10px] font-bold leading-none">{badge}</span>
      )}
    </div>
  );
}
