import type { RealtimeChannel } from '@supabase/supabase-js';
import { createNewGame, listMoves } from '@/game/engine';
import type { GameState } from '@/game/engine';
import { useMatchStore } from '@/store/matchStore';
import { supabase } from './supabase';

let channel: RealtimeChannel | null = null;
let stopStoreListener: (() => void) | null = null;
let applyingRemote = false;

/** Start a fresh online game (both phones begin from the same position). */
export function startOnlineMatch(myColor: 'white' | 'black'): void {
  useMatchStore.setState({
    mode: 'online',
    playerColor: myColor,
    gameState: createNewGame('white'),
    selectedPoint: null,
    legalMoves: [],
    targetMoves: [],
    history: [],
    aiThinking: false,
    turnTimeLeft: 45,
    warnings: { white: 0, black: 0 },
    timeoutMessage: null,
  });
}

export function stopOnlineSync(): void {
  stopStoreListener?.();
  stopStoreListener = null;
  if (channel && supabase) {
    void supabase.removeChannel(channel);
  }
  channel = null;
}

/**
 * Keep both phones in sync through one realtime channel per room.
 * Every local change of the game state is sent to the opponent.
 */
export function startOnlineSync(roomId: string): () => void {
  const client = supabase;
  if (!client) return () => {};

  stopOnlineSync();

  const ch = client.channel(`nard-room-${roomId}`, {
    config: { broadcast: { self: false } },
  });
  channel = ch;

  const sendState = () => {
    const gameState = useMatchStore.getState().gameState;
    if (!gameState) return;
    void ch.send({
      type: 'broadcast',
      event: 'state',
      payload: { gameState },
    });
  };

  // The opponent changed something -> show the same position here.
  ch.on('broadcast', { event: 'state' }, ({ payload }) => {
    const incoming = payload?.gameState as GameState | undefined;
    if (!incoming) return;

    const { gameState: prev, playerColor } = useMatchStore.getState();
    const changed =
      !prev || prev.turn !== incoming.turn || prev.phase !== incoming.phase;
    const myMove = incoming.turn === playerColor && incoming.phase === 'moving';

    applyingRemote = true;
    useMatchStore.setState({
      gameState: incoming,
      selectedPoint: null,
      targetMoves: [],
      history: [],
      legalMoves: myMove ? listMoves(incoming) : [],
      ...(changed ? { turnTimeLeft: 45 } : {}),
    });
    applyingRemote = false;
  });

  // A phone that joins late asks for the current position.
  ch.on('broadcast', { event: 'hello' }, () => sendState());

  ch.subscribe((status) => {
    if (status === 'SUBSCRIBED') {
      void ch.send({ type: 'broadcast', event: 'hello', payload: {} });
    }
  });

  // My own changes -> send to the opponent.
  stopStoreListener = useMatchStore.subscribe((state, prev) => {
    if (applyingRemote) return;
    if (state.gameState && state.gameState !== prev.gameState) sendState();
  });

  return stopOnlineSync;
}
