import { useEffect, type ReactNode } from 'react';
import { useAppStore, type AppScreen } from '@/store/appStore';
import { useTelegramBackButton } from '@/hooks/useTelegramBackButton';
import { useViewportSize } from '@/hooks/useViewportSize';
import {
  WebApp,
  enterLandscapeMode,
  leaveLandscapeMode,
} from '@/services/telegram';
import { IntroSplashScreen } from '@/screens/IntroSplash/IntroSplashScreen';
import { MainMenuScreen } from '@/screens/MainMenu/MainMenuScreen';
import { SearchOpponentScreen } from '@/screens/SearchOpponent/SearchOpponentScreen';
import { MatchSetupScreen } from '@/screens/MatchSetup/MatchSetupScreen';
import { GameBoardScreen } from '@/screens/GameBoard/GameBoardScreen';
import { SettingsScreen } from '@/screens/Settings/SettingsScreen';

// حداقل فضای خالی برای دکمه‌های تلگرام در حالت تمام‌صفحه
const TELEGRAM_BAR_MIN = '84px';

/**
 * Full-screen frame for the game only.
 * If the phone is still upright, only THIS frame is turned 90 degrees.
 * Leaves a free strip so Telegram's floating buttons never cover the board.
 */
function GameFrame({ children }: { children: ReactNode }) {
  const { width, height } = useViewportSize();
  const portrait = height > width;

  useEffect(() => {
    void enterLandscapeMode();
    return () => leaveLandscapeMode();
  }, []);

  const isFullscreen = Boolean(
    (WebApp as unknown as { isFullscreen?: boolean }).isFullscreen,
  );
  const strip = isFullscreen
    ? `max(calc(var(--tg-safe-area-inset-top, 0px) + var(--tg-content-safe-area-inset-top, 0px)), ${TELEGRAM_BAR_MIN})`
    : '0px';

  const style = portrait
    ? {
        width: height,
        height: width,
        transform: `translateX(${width}px) rotate(90deg)`,
        transformOrigin: 'top left',
        paddingLeft: strip,
      }
    : { width, height, paddingTop: strip };

  return (
    <div className="fixed left-0 top-0 z-40 overflow-hidden bg-night" style={style}>
      {children}
    </div>
  );
}

function ScreenRouter({ screen }: { screen: AppScreen }) {
  const goToMenu = useAppStore((s) => s.goToMenu);

  switch (screen) {
    case 'boot':
      return null;
    case 'intro':
      return <IntroSplashScreen />;
    case 'menu':
      return <MainMenuScreen />;
    case 'search':
      return <SearchOpponentScreen />;
    case 'setup':
      return <MatchSetupScreen />;
    case 'game':
      return <GameBoardScreen onExit={goToMenu} />;
    case 'settings':
      return <SettingsScreen />;
    default: {
      const _exhaustive: never = screen;
      return _exhaustive;
    }
  }
}

export function App() {
  const screen = useAppStore((s) => s.screen);
  useTelegramBackButton();

  useEffect(() => {
    if ((window as any).Telegram?.WebApp) {
      const tg = (window as any).Telegram.WebApp;
      tg.ready();
      tg.expand();
    }
  }, []);

  if (screen === 'game') {
    return (
      <GameFrame>
        <ScreenRouter screen={screen} />
      </GameFrame>
    );
  }

  return (
    <main
      className="w-screen min-h-screen bg-night text-cream flex justify-center items-center overflow-hidden relative"
      data-screen={screen}
    >
      <div className="w-full max-w-md h-full min-h-screen relative overflow-hidden bg-stone-900 flex flex-col">
        <ScreenRouter screen={screen} />
      </div>
    </main>
  );
}

export default App;
